package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import com.ruoyi.paiflow.domain.RunRecord;
import com.ruoyi.paiflow.mapper.ToolMapper;
import java.util.*;
import static com.ruoyi.paiflow.service.ModelOperationJson.error;

/** 上游Plugin已接受完成输出还须等于同租约中心真实Tool回执的原类型/default投影。 */
final class ToolCompletedSources {
 static void verify(RunRecord run,JSONObject execution,JSONObject target,JSONArray events,ToolMapper mapper){var inputs=target.getJSONObject("data").getJSONArray("inputs");if(inputs==null)return;var checked=new HashSet<String>();for(Object raw:inputs){var field=(JSONObject)raw;var binding=field.getJSONObject("schema").getJSONObject("value");if(!"ref".equals(binding.get("type")))continue;String id=binding.getJSONObject("content").getString("nodeId");if(id==null||!id.startsWith("plugin::")||!checked.add(id))continue;var node=DataWorkerOperationService.find(execution,id);if(node==null)throw error("工具输入源不属于固定图",403);JSONObject accepted=null;for(Object value:events){var event=(JSONObject)value;if(id.equals(event.get("nodeId"))&&"node.completed".equals(event.get("eventType"))&&event.get("iterationId")==null){var payload=event.getJSONObject("payload");var frame=payload==null?null:payload.getJSONObject("legacyFrame");var step=frame==null?null:frame.getJSONObject("workflow_step");var completed=step==null?null:step.getJSONObject("node");if(completed!=null&&id.equals(completed.get("id")))accepted=completed.getJSONObject("outputs");}}if(accepted==null)throw error("上游工具没有当前已接受完成输出",403);var rows=mapper.nodeOperations(run.getId(),run.getLeaseId(),run.getAttempt(),id);if(rows.size()!=1||!"COMPLETED".equals(rows.getFirst().get("state"))||!(rows.getFirst().get("responseJson") instanceof String receipt))throw error("上游工具没有同租约中心成功账本",403);JSONObject response;try{response=JSON.parseObject(receipt);if(response.getJSONObject("header").getIntValue("code")!=0)throw new IllegalArgumentException();Object outputs=JSON.parse(response.getJSONObject("payload").getJSONObject("text").getString("text"));if(!ToolSchema.same(accepted,project(node,outputs)))throw error("上游工具完成输出偏离真实生产回执",409);}catch(com.ruoyi.common.exception.ServiceException e){throw e;}catch(RuntimeException e){throw error("上游工具生产回执无效",409);}}}
 static JSONObject completed(RunRecord run,JSONObject node,ToolMapper mapper){var rows=mapper.nodeOperations(run.getId(),run.getLeaseId(),run.getAttempt(),node.getString("id"));if(rows.size()!=1||!"COMPLETED".equals(rows.getFirst().get("state"))||!(rows.getFirst().get("responseJson") instanceof String receipt))throw error("上游工具没有同租约中心成功账本",403);try{var response=ModelMessageSources.sourceObject(receipt);if(response.getJSONObject("header").getIntValue("code")!=0)throw new IllegalArgumentException();Object output=JSON.parse(response.getJSONObject("payload").getJSONObject("text").getString("text"));if("java".equals(run.getEngineProfile())){javaBinding(run,node,rows.getFirst());return JavaToolSemantics.project(output);}return project(node,output);}catch(com.ruoyi.common.exception.ServiceException e){throw e;}catch(RuntimeException e){throw error("上游工具生产回执无效",409);}}
 private static void javaBinding(RunRecord run,JSONObject node,Map<String,Object> row){var task=ModelMessageSources.sourceObject(run.getAssignmentJson());String resource=node.getJSONObject("data").getJSONObject("nodeParam").getString("toolResourceId");var d=task.getJSONObject("resourceSnapshots").getJSONObject(resource);ToolNodeCompiler.descriptor(resource,d);var b=ModelMessageSources.sourceObject((String)row.get("bindingJson"));if(!Objects.equals(run.getId(),b.get("runId"))||!Objects.equals(run.getLeaseId(),b.get("leaseId"))||!Objects.equals(run.getAttempt(),b.getInteger("attempt"))||!Objects.equals(Long.toString(run.getWorkflowVersionId()),b.get("workflowVersionId"))||!Objects.equals(task.get("dslHash"),b.get("dslHash"))||!Objects.equals(node.get("id"),b.get("nodeId"))||b.get("iterationId")!=null||!Objects.equals(resource,b.get("resourceId"))||!Objects.equals(d.get("version"),b.get("resourceVersion"))||!"tool".equals(b.get("kind"))||!"spark-link".equals(b.get("provider")))throw error("Java工具来源账本固定范围不一致",403);}
 static JSONObject project(JSONObject node,Object output){if(!(output instanceof JSONObject raw))throw error("原Plugin对象输出无效",409);var result=new JSONObject();var fields=node.getJSONObject("data").getJSONArray("outputs");if(fields==null)return result;for(Object value:fields){if(!(value instanceof JSONObject field)||field.getJSONObject("schema")==null||!(field.get("name") instanceof String name)||result.containsKey(name))throw error("原Plugin输出声明无效",409);String type=field.getJSONObject("schema").getString("type");Object actual=raw.get(name);boolean valid=switch(type==null?"":type){case "string"->actual instanceof String;case "object"->actual instanceof JSONObject;case "array"->actual instanceof JSONArray;case "boolean"->actual instanceof Boolean;case "integer"->actual instanceof Byte||actual instanceof Short||actual instanceof Integer||actual instanceof Long||actual instanceof java.math.BigInteger;case "number"->actual instanceof Number;default->throw error("原Plugin输出Schema类型无效",409);};Object fallback=switch(type){case "string"->"";case "object"->new JSONObject();case "array"->new JSONArray();case "boolean"->false;case "integer"->0;case "number"->0.0;default->null;};result.put(name,valid?actual:fallback);}return result;}
}
